scr.script:
			// variable used to return custom message
var ruleMessage;
// variable used to return the type of the rule Error
// or Warning and red/blue color will be used for result
// if another custom type is returned (Problem in the rule below) 
// then result is colored in yellow
var errType;
var table;
function checkcomments(object){
 result = true;
 ruleMessage="";
 if(table.getCommentInRDBMS().equals("")){
  ruleMessage="no comments in RDBMS defined";
  errType="Problem:";
  result = false;
 }
 if(table.getComment().equals("")){
  if(ruleMessage.equals("")){
   ruleMessage="no comments defined";
  }else{
   ruleMessage= ruleMessage +" , no comments defined";
   }
   // can be changed to Warning    
   errType="Error";
  return false;
 }
 return result;
}
//rule for not null constraint name
function NotNullConstr_Name_Length(column){
 model = column.getDesignPart();
 name = column.getNotNullConstraintName();
 result = true;
 if(name!=null && !"".equals(name)){
	holder = model.getNamingOptionsHolderFor("oracle.dbtools.crest.model.design.constraint.TableLevelConstraint");
	if ((holder.getMaxNameLength() > 0) && (name.length() > holder.getMaxNameLength())) {
		result = false;
	}
 }
 return result
}

			// columns are found by column name
// allowing reuse of already existing columns
// dynamic property ctemplateID is set afterwards - will keep connection to template
// column even if the name of column is changed
var t_name = "table_template";
var p_name = "ctemplateID";
template = model.getTableSet().getByName(t_name);
if(template!=null){
    tcolumns = template.getElements();
    tables = model.getTableSet().toArray();
    for (var t = 0; t<tables.length;t++){
     table = tables[t];
    // compare name ignoring the case
     if(!table.getName().equalsIgnoreCase(t_name)){
         for (var i = 0; i < tcolumns.length; i++) {
            column = tcolumns[i];
            col = table.getElementByName(column.getName());
            if(col==null){
             col = table.getColumnByProperty(p_name,column.getObjectID());
            }
            if(col==null){
             col = table.createColumn();
            }
            column.copy(col);
            //set property after copy otherwise it'll be cleared by copy
            col.setProperty(p_name,column.getObjectID());
            table.setDirty(true);
         }
     }
    }
}

			objs = model.getLastSearchResult().toArray();
var dp;
var sv;
//create subview and add tables to it
for(var i = 0;i<objs.length;i++){
	obj = objs[i];
	// use "Entity" for entities and logical model
	if(obj.getObjectTypeName().equals("Table")){
		if(dp==null){
			dp = obj.getDesignPart();
			sv = dp.createDesignPartSubView();
			// uncomment next line if want to set name
		     //sv.setName("Name");
		     sv.getPlaceHolder().setVisible(true);
		}
		sv.addViewFor(obj);
	}
}
if(dp!=null){
 //add foreign keys if you want to
 for(var i = 0;i<objs.length;i++){
	obj = objs[i];
	// use "Entity" for entities and logical model
	if(obj.getObjectTypeName().equals("Table")){
		tv = obj.getFirstViewForDPV(sv);
		if(tv!=null){
			//for entities and logical model use 
			//tv.addTVRelations(); 
			tv.addTVFKRelations();
		}
	}
 }
 //add Arcs if you want to
 for(var i = 0;i<objs.length;i++){
	obj = objs[i];
	if(obj.getObjectTypeName().equals("Table")){
		tv = obj.getFirstViewForDPV(sv);
		if(tv!=null){
			tv.addArcs();
		}
	}
 }
 //arrange diagram
 sv.rearrangeNewDiagram();
}

			var gLogNote = "LOG";
var gCurrentLang = "DE";
var gLanguages = "DE,EN";
var gTranslInforegexp =/TRANSLATION\{[^}]*\}/;
var logInitialized = false;

function initLog(){
	if (! logInitialized){
		var lNote = model.getNoteSet().getByName(gLogNote);
     	if (lNote == null) {
    	    		lNote = model.createNote()
	    		lNote.setName(gLogNote);
     	}
     	lNote.setComment("");
     	logInitialized = true;
	}
}
function log(plog){
	initLog();
	var lNote = model.getNoteSet().getByName(gLogNote);
     lNote.setComment(lNote.getComment()+"\n"+plog);
}

function getTranslInfo(){
	var lDesignComment = model.design.getComment();
     lmatchTransl= lDesignComment.match(gTranslInforegexp);
     return lmatchTransl;    
}

function setTranslInfo(curLang,langs) {
	model.design.setComment(
		"TRANSLATION{\ncurrentLang="
		+curLang+"\nlanguages="
		+langs+"\nlastSync=\n}\n"
		+ model.design.getComment());
}
function updTranslInfo(curLang,langs,datetime) {
	curComment = model.design.getComment();
	model.design.setComment(
		curComment.replace(gTranslInforegexp,
		"TRANSLATION{\ncurrentLang="
		+curLang+"\nlanguages="
		+langs+"\nlastSync="+datetime+"\n}"
		));
}

function textFromNote(lang,obj) {
	return obj.getNotes()
}

function textToNote(lang,obj,value) {
	obj.setNotes(value)
}

function init(){
	lmatchTransl = getTranslInfo();
	if (lmatchTransl == null) {
		throw new Error("***TRANSLATION not installed***");
	}
	ltext= String(lmatchTransl).match(/currentLang=[A-Z]{2}/);
	lparts = String(ltext).split("=");
	//log("curLang="+lparts[1]);
     gCurrentLang = lparts[1];

	ltext= String(lmatchTransl).match(/languages=[A-Z,]*/);
	lparts = String(ltext).split("=");
     //log("languages="+lparts[1]);
     gLanguages = lparts[1]
}

function doProperty(lang,propName,obj,value){
	lpropName = lang + propName;
	if (lang == gCurrentLang) {
		// die Werte kommen aus dem Objekt, überschreibe immer
		obj.setProperty(lpropName
		      	 	,value)
	} else {
	   	ldest = obj.getProperty(lpropName);
	   	// überschreibe nur, wenn das Ziel leer ist
		if (ldest == '')  {
		 	// bei leerem sourceWert setze keinen Prefix
			if (value != '') {
				lprefix =  '*'+gCurrentLang+'* '
				obj.setProperty(lpropName,lprefix+value)
			} 

		}
	}
}

function doNote(lang,obj,value) {
	startStr = '['+lang+'['
	endStr = ']'+lang+']'
	if (lang == gCurrentLang) {
		// die Werte kommen aus dem Objekt, überschreibe immer
		textToNote(lang,obj,value)
	} else {
	   	ldest = textFromNote(lang,obj);
	   	// überschreibe nur, wenn das Ziel leer ist
		if (ldest == '')  {
		 	// bei leerem sourceWert setze keinen Prefix
			if (value != '') {
				lprefix =  '*'+gCurrentLang+'* '
				textToNote(lang,obj,lprefix+value)
			} 

		}
	}

}			

function fuellUDP(){
	entities = model.getEntitySet().toArray();
	for (i=0;i<entities.length;i++) { //
		ent = entities[i];
		// noch nicht initialisiert
		doProperty("DE","_ENTI_NAME",ent,ent.getName())
//		doProperty("DE","_ENTI_COMMENT",ent,ent.getComment())
		doNote("DE",ent,ent.getComment())
		doProperty("DE","_ENTI_SYNONYM",ent,ent.getSynonym())
		doProperty("EN","_ENTI_NAME",ent,ent.getName())
//		doProperty("EN","_ENTI_COMMENT",ent,ent.getComment())
		doNote("EN",ent,ent.getComment())
		doProperty("EN","_ENTI_SYNONYM",ent,ent.getSynonym())

		attrs = ent.getAttributes().toArray();
		//log("Attrs="+attrs.length)
		for (j=0;j<attrs.length;j++) { //
			attr = attrs[j];
			//log(attr.getName(),attr.getComment());
			doProperty("DE","_ATTR_NAME",attr,attr.getName());
//			doProperty("DE","_ATTR_COMMENT",attr,attr.getComment());			
			doNote("DE",attr,attr.getComment());			
			doProperty("EN","_ATTR_NAME",attr,attr.getName());
//			doProperty("EN","_ATTR_COMMENT",attr,attr.getComment());			
			doNote("EN",attr,attr.getComment());			
		}
		ent.setDirty(true);
	}
	relationships = model.getRelationSet().toArray();
	for (r=0;r<relationships.length;r++) { //
		rel = relationships[r];
		sourcename = rel.getNameOnSource()
		targetname = rel.getNameOnTarget()
		doProperty("DE","_RELA_TEXT_FROM",rel,sourcename)
		doProperty("DE","_RELA_TEXT_TO",rel,targetname)
		doProperty("EN","_RELA_TEXT_FROM",rel,sourcename)
		doProperty("EN","_RELA_TEXT_TO",rel,targetname)
		rel.setDirty(true);
	}
}

function setProperties(lang){
	entities = model.getEntitySet().toArray();
	for (i=0;i<entities.length;i++) { //
		ent = entities[i];
		ent.setName(ent.getProperty(lang+"_ENTI_NAME"));
//		ent.setComment(ent.getProperty(lang+"_ENTI_COMMENT"));
		ent.setComment(textFromNote(lang,ent))
		ent.setSynonym(ent.getProperty(lang+"_ENTI_SYNONYM"));

		attrs = ent.getAttributes().toArray();
		//log("Attrs="+attrs.length)
		for (j=0;j<attrs.length;j++) { //
			attr = attrs[j];
			//log(attr.getName(),attr.getComment());
			attr.setName(attr.getProperty(lang+"_ATTR_NAME"));
//			attr.setComment(attr.getProperty(lang+"_ATTR_COMMENT"));			
			attr.setComment(textFromNote(lang,attr))
		}		
		ent.setDirty(true);
	}
	relationships = model.getRelationSet().toArray();
	for (r=0;r<relationships.length;r++) { 
		rel = relationships[r];
		rel.setNameOnSource(rel.getProperty(lang+"_RELA_TEXT_FROM"));
		rel.setNameOnTarget(rel.getProperty(lang+"_RELA_TEXT_TO"));
		rel.setDirty(true);
	}
}

function curDateStr(){
	var currentdate = new Date();
	return  currentdate.getDate() 
	+ "/" + (currentdate.getMonth()+1) 
	+ "/" + currentdate.getFullYear() + "  " 
	+ currentdate.getHours() + ":" 
	+ currentdate.getMinutes() + ":" + currentdate.getSeconds();
}
function initTranslation() {
	lmatchTransl= getTranslInfo()
	if (lmatchTransl == null) {
		setTranslInfo(gCurrentLang
		,gLanguages);		
	} else {
		throw new Error("***TRANSLATION already installed***");
	}
	//hier gibt es einen Eintrag für die Translation
	init();
	// fülle die UDP für die Übersetzungen
	fuellUDP();
	updTranslInfo(gCurrentLang, gLanguages
				,curDateStr());
	model.design.setDirty(true);
}


function changeLang(pfromLang,ptoLang){
	//log("3:"+gLanguages);
//	log("change from " + pfromLang + " to " + ptoLang);
	fuellUDP();
	setProperties(ptoLang);
	gCurrentLang = ptoLang;
	updTranslInfo(gCurrentLang, gLanguages
				,curDateStr());	
	model.design.setDirty(true);
}

function change2DE() {
	init();
	if (gCurrentLang != 'DE') {
		changeLang(gCurrentLang,'DE');
	}
}

function change2EN() {
	init();
	if (gCurrentLang != 'EN') {
		changeLang(gCurrentLang,'EN');
	}
}

